// Build the ElevenLabs knowledge-base documents from the portfolio's source of truth.
//
// Reads src/data/{projects,experience,skills}.ts and emits one focused markdown
// document per project plus a project index, an experience doc, and a skills doc
// into elevenlabs/knowledge-base/. These files are GENERATED — do not edit them by
// hand. Edit the source data files and re-run `npm run kb:build`.
//
// The hand-written curated docs (00-start-here, 01-profile, 02-education, 05-faq,
// 06-portfolio-site) are NEVER touched by this script.
//
// Run: npm run kb:build   (node --experimental-strip-types scripts/build-elevenlabs-kb.mjs)

import { writeFileSync, mkdirSync, readdirSync, rmSync, existsSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

import { projects } from "../src/data/projects.ts";
import { experiences } from "../src/data/experience.ts";
import { skillGroups } from "../src/data/skills.ts";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, "..");
const KB = join(ROOT, "elevenlabs", "knowledge-base");
const PROJECTS_DIR = join(KB, "projects");

const SITE = "https://azizu.dev";
const GITHUB = "https://github.com/azizu06";
const LINKEDIN = "https://www.linkedin.com/in/abduaziz-umarov/";

const GENERATED_BANNER =
  "<!-- GENERATED by scripts/build-elevenlabs-kb.mjs — do not edit by hand. Edit src/data/*.ts and run `npm run kb:build`. -->";

/** Turn a project title into a stable kebab-case file slug. */
function slugify(title) {
  return title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

/** Pick the right indefinite article for a phrase. */
function article(word) {
  return /^[aeiou]/i.test(word) ? "an" : "a";
}

/** Join a list into a readable "a, b, and c" string. */
function humanList(items) {
  if (!items || items.length === 0) return "";
  if (items.length === 1) return items[0];
  if (items.length === 2) return `${items[0]} and ${items[1]}`;
  return `${items.slice(0, -1).join(", ")}, and ${items[items.length - 1]}`;
}

/** Render one project document. Kept rich so it always clears the 500-byte RAG floor. */
function renderProject(p) {
  const lines = [];
  lines.push(GENERATED_BANNER);
  lines.push("");
  lines.push(`# ${p.title}`);
  lines.push("");
  lines.push(
    `${p.title} is one of my (Aziz Umarov's) ${p.category} projects, dated ${p.date}.` +
      (p.award ? ` It won ${p.award}.` : ""),
  );
  lines.push("");

  lines.push("## Summary");
  lines.push(p.description);
  lines.push("");

  if (p.details) {
    lines.push("## What it is");
    lines.push(p.details);
    lines.push("");
  }

  if (p.keyFeatures && p.keyFeatures.length) {
    lines.push("## Key features");
    for (const f of p.keyFeatures) lines.push(`- ${f}`);
    lines.push("");
  }

  lines.push("## Tech stack");
  lines.push(humanList(p.technologies) + ".");
  lines.push("");

  lines.push("## Links");
  if (p.liveHref) lines.push(`- Live demo: ${p.liveHref}`);
  if (p.githubHref) lines.push(`- Source code: ${p.githubHref}`);
  if (p.award) lines.push(`- Recognition: ${p.award}`);
  lines.push("");

  // A short conversational block helps the voice agent answer naturally and
  // gives retrieval extra phrasing/keywords to match against.
  const topTech = humanList(p.technologies.slice(0, 4));
  // Lowercase the leading word only when it's an ordinary Capitalized word, so
  // acronyms like "AI" aren't mangled into "aI".
  const descLower = /^[A-Z][a-z]/.test(p.description)
    ? `${p.description.charAt(0).toLowerCase()}${p.description.slice(1)}`
    : p.description;
  const descArticle = article(descLower.split(/\s+/)[0]);
  lines.push("## How I talk about this project");
  lines.push(
    `If someone asks me about ${p.title}, I'd tell them it's ${descArticle} ${descLower} ` +
      `I built it with ${topTech}.` +
      (p.award ? ` It won ${p.award}.` : "") +
      (p.liveHref ? ` I can point them to the live demo at ${p.liveHref}` : "") +
      (p.githubHref ? ` and the source on my GitHub at ${p.githubHref}.` : "."),
  );
  lines.push("");
  lines.push(`Keywords: ${p.title}, ${p.category}, ${p.technologies.join(", ")}.`);
  lines.push("");

  return lines.join("\n");
}

/** Render the project index / catalog. */
function renderProjectIndex() {
  const byCategory = new Map();
  for (const p of projects) {
    if (!byCategory.has(p.category)) byCategory.set(p.category, []);
    byCategory.get(p.category).push(p);
  }

  const lines = [];
  lines.push(GENERATED_BANNER);
  lines.push("");
  lines.push("# Projects index");
  lines.push("");
  lines.push(
    `I (Aziz Umarov) have ${projects.length} projects on my portfolio, spanning AI products, full-stack web apps, ` +
      `React apps, games, and front-end fundamentals. This index helps find the right project; each project also ` +
      `has its own document with more detail. Live demos are on my portfolio at ${SITE}/projects.`,
  );
  lines.push("");

  const flagship = projects.filter((p) => p.award || p.category === "AI product");
  if (flagship.length) {
    lines.push("## Flagship and award-winning projects");
    for (const p of flagship) {
      lines.push(`- ${p.title}${p.award ? ` (${p.award})` : ""}: ${p.description}`);
    }
    lines.push("");
  }

  lines.push("## All projects by category");
  for (const [category, items] of byCategory) {
    lines.push(`### ${category}`);
    for (const p of items) {
      const live = p.liveHref ? ` — live: ${p.liveHref}` : "";
      lines.push(`- ${p.title} (${p.date}): ${p.description}${live}`);
    }
    lines.push("");
  }

  return lines.join("\n");
}

/** Render the experience doc from experience.ts. */
function renderExperience() {
  const lines = [];
  lines.push(GENERATED_BANNER);
  lines.push("");
  lines.push("# Experience");
  lines.push("");
  lines.push(
    "My (Aziz Umarov's) professional and research experience. I'm an early-career software engineer and UCF " +
      "computer science student, currently balancing an industry developer role with undergraduate AI research.",
  );
  lines.push("");
  for (const e of experiences) {
    lines.push(`## ${e.role} — ${e.company}`);
    lines.push(`- Period: ${e.period}`);
    lines.push(`- Location: ${e.location}`);
    lines.push(`- Technologies: ${humanList(e.technologies)}.`);
    lines.push("");
    lines.push(e.summary);
    lines.push("");
  }
  lines.push("## How I talk about my experience");
  lines.push(
    "When someone asks what I do or where I work, I lead with my Knight Hacks software developer role " +
      "and my ISUE Lab research on AI speech-therapy feedback, then offer to go deeper on either one.",
  );
  lines.push("");
  return lines.join("\n");
}

/** Render the skills doc from skills.ts. */
function renderSkills() {
  const lines = [];
  lines.push(GENERATED_BANNER);
  lines.push("");
  lines.push("# Skills");
  lines.push("");
  lines.push(
    "My (Aziz Umarov's) technical skills, grouped by area. These are interview-defensible skills I actually use " +
      "across my projects, research, and Knight Hacks work — not an aspirational list.",
  );
  lines.push("");
  for (const g of skillGroups) {
    lines.push(`## ${g.title}`);
    lines.push(humanList(g.skills) + ".");
    lines.push("");
  }
  lines.push("## How I talk about my skills");
  lines.push(
    "My strongest throughline is full-stack TypeScript, React, and Next.js plus practical AI engineering " +
      "(OpenAI, RAG, embeddings, PyTorch). I also have real cloud and DevOps exposure (AWS, Docker, Kubernetes, CI/CD). " +
      "If someone asks what I'm best at, I emphasize full-stack web plus applied AI, and point to CrisisLens, PopChoice, " +
      "and my ISUE Lab research as proof.",
  );
  lines.push("");
  return lines.join("\n");
}

// --- write everything -------------------------------------------------------

mkdirSync(PROJECTS_DIR, { recursive: true });

// Clean stale generated project files (projects/ only ever holds generated docs).
if (existsSync(PROJECTS_DIR)) {
  for (const f of readdirSync(PROJECTS_DIR)) {
    if (f.endsWith(".md")) rmSync(join(PROJECTS_DIR, f));
  }
}

let smallest = Infinity;
let smallestName = "";
const written = [];

for (const p of projects) {
  const content = renderProject(p);
  const bytes = Buffer.byteLength(content, "utf8");
  if (bytes < smallest) {
    smallest = bytes;
    smallestName = p.title;
  }
  if (bytes < 500) {
    console.warn(
      `  ⚠ ${p.title} is ${bytes} bytes (< 500) and will NOT be RAG-indexed by ElevenLabs.`,
    );
  }
  const file = join(PROJECTS_DIR, `${slugify(p.title)}.md`);
  writeFileSync(file, content, "utf8");
  written.push(file);
}

writeFileSync(join(PROJECTS_DIR, "index.md"), renderProjectIndex(), "utf8");
writeFileSync(join(KB, "03-experience.md"), renderExperience(), "utf8");
writeFileSync(join(KB, "04-skills.md"), renderSkills(), "utf8");

console.log(`✓ Wrote ${written.length} project docs + index, experience, skills`);
console.log(`✓ Output: ${KB}`);
console.log(
  `✓ Smallest project doc: "${smallestName}" at ${smallest} bytes ` +
    `(RAG floor is 500 bytes — ${smallest >= 500 ? "all clear" : "SOME DOCS TOO SMALL"})`,
);
